                {
                    if (kvp.Value.Contains(current) && !dependents.Contains(kvp.Key))
                    {
                        dependents.Add(kvp.Key);
                        toCheck.Enqueue(kvp.Key);
                    }
                }
            }

            return dependents;
        }

